/*
 * A213756  Rectangular array: (row n) = b**c, where b(h) = -1 + 2^h, c(h) =
 *          2*n - 3 + 2*h, n>=1, h>=1, and ** = convolution.
 * https://oeis.org/A213756
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabl, easy
 * Formula:   a(n) is the nth term when the rectangular array T(r,c) =
 *            Σ_{h=1}^{c} (2^h−1) · (2·(r+c−h)−1) (r,c) being the row and
 *            column indices of the nth term in the “falling antidiagonal”
 *            reading. The array is generated by convolving b(h) = 2^h−1 (h≥1)
 *            with c(h) = 2·n−3+2·h (h≥1)
 * Range:     u8 n <= 15, u16 n <= 91, u32 n <= 435, u64 n <= 820,
 *            u128 n <= 820, big any n
 * Helpers:   pow2
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include "../utils/pow2.h"

/* Compute a(n) for n >= 1.
   The sequence is read by falling antidiagonals of the array T. */
seq_t a(idx_t m)
{
    if (m == 0) return (seq_t)0;        /* undefined, but safe */
    /* Find minimal s ≥ 2 such that s*(s-1)/2 ≥ m */
    idx_t s = 2;
    while ( (unsigned __int128)s * (s - 1) / 2 < m ) ++s;
    /* Previous cumulative count */
    idx_t prev = (unsigned __int128)(s - 2) * (s - 1) / 2;
    idx_t offset = m - prev - 1;   /* 0‑based offset within the diagonal */
    idx_t row = offset + 1;        /* r */
    idx_t col = (s - 1) - offset;  /* c */

    /* Compute T(row, col) via the closed‑form sum. */
    seq_t two_pow_kp1 = pow2(col + 1);          /* 2^(k+1) */
    seq_t sumA = two_pow_kp1 - (seq_t)col - (seq_t)2;
    seq_t temp1 = ((seq_t)(col - 1)) * two_pow_kp1;
    seq_t temp2 = temp1 + (seq_t)2;
    seq_t temp3 = (seq_t)col * ((seq_t)col + (seq_t)1) / 2;
    seq_t sumH = temp2 - temp3;
    seq_t C = (seq_t)2 * ((seq_t)row + (seq_t)col) - (seq_t)1;
    seq_t result = C * sumA - (seq_t)2 * sumH;
    return result;
}
